+	if resolved, err := filepath.EvalSymlinks(abs); err == nil {
+		abs = resolved
+	}
+	parent := filepath.Dir(abs)
+	if parent == abs || filepath.Dir(parent) == parent {
+		return abs
+	}
+	return parent
+}
