diff --git a/internal/cli/setup_spawn.go b/internal/cli/setup_spawn.go
new file mode 100644
index 00000000..f478fbb7
--- /dev/null
+++ b/internal/cli/setup_spawn.go
@@ -0,0 +1,133 @@
+package cli
+import (
+	"errors"
+	"fmt"
+	"os"
+	"os/exec"
+	"path/filepath"
+	"strings"
+)
+func spawnDetached(plan setupBackfillPlan) (int, error) {
+	if plan.Binary == "" {
+		return 0, fmt.Errorf("no executable to run")
+	}
+	if plan.LogPath != "" {
+		if err := os.MkdirAll(filepath.Dir(plan.LogPath), 0o700); err != nil {
+			return 0, fmt.Errorf("create log directory: %w", err)
+		}
+	}
+	cmd := exec.Command(plan.Binary, plan.Args...)
+	cmd.Dir = plan.Dir
+	cmd.Env = plan.Env
+	cmd.SysProcAttr = detachedSysProcAttr()
+	devNull, err := os.OpenFile(os.DevNull, os.O_RDWR, 0)
+	if err != nil {
+		return 0, fmt.Errorf("open %s: %w", os.DevNull, err)
+	}
+	defer func() { _ = devNull.Close() }()
+	cmd.Stdin = devNull
+	var log *os.File
+	if plan.LogPath != "" {
+		log, err = os.OpenFile(plan.LogPath, os.O_CREATE|os.O_WRONLY|os.O_APPEND|noFollowOpenFlag, 0o600)
+		if err != nil {
+			return 0, fmt.Errorf("open backfill log: %w", err)
+		}
+		defer func() { _ = log.Close() }()
+		cmd.Stdout = log
+		cmd.Stderr = log
+	} else {
+		cmd.Stdout = devNull
+		cmd.Stderr = devNull
+	}
+	if err := cmd.Start(); err != nil {
+		return 0, fmt.Errorf("start background backfill: %w", err)
+	}
+	pid := cmd.Process.Pid
+	if err := cmd.Process.Release(); err != nil {
+		return pid, nil
+	}
+	return pid, nil
+}
+func stopDetachedProcess(pid int) error {
+	if pid <= 0 {
+		return fmt.Errorf("invalid pid %d", pid)
+	}
+	proc, err := os.FindProcess(pid)
+	if err != nil {
+		return fmt.Errorf("find process %d: %w", pid, err)
+	}
+	if err := proc.Kill(); err != nil {
+		return fmt.Errorf("kill process %d: %w", pid, err)
+	}
+	return nil
+}
+func backfillRunning(brainDir string, pid int) bool {
+	if !processAlive(pid) {
+		return false
+	}
+	if strings.TrimSpace(brainDir) == "" {
+		return true
+	}
+	lock, err := acquireFileLock(filepath.Join(brainDir, brainLockDirName, brainDistillLockName), "distill_pass_locked", 0)
+	if err != nil {
+		if errors.Is(err, errFileLockTimeout) {
+			return true
+		}
+		return true
+	}
+	_ = lock.Close()
+	return false
+}


