            arms=arms, force_empty_packet=args.null_test, resume=not args.no_resume,
            rep=rep, backend=args.backend, model=args.model, model_role=args.model_role,
            sealed_pairs=sealed_pairs,
        ))

    print(_harness.pretty_json([
