import pathlib,json,datetime,subprocess,shutil
out=pathlib.Path('/Users/thomi/.codex/reviews/entire-brain-2026-09-10'); evidence=out/'fix-evidence';evidence.mkdir(exist_ok=True)
notes={97:'Nonblocking, no-follow descriptor validation shared by diagnostics and queries; alias checks; bounded 64 MiB index reads and writes. Oversized writes preserve the prior index.',111:'Three-way fact merge from a frozen baseline preserves concurrent fields, reactivation, deletion, provenance, and relationship additions/removals.',128:'Reader capacity accounts for delimiters, with an explicit record-size check. Exact-limit NDJSON round trips, including CRLF and EOF.',174:'Agent state paths include the resolved result cell in the opaque hash, separating independent runs while preserving resume identity.',190:'Prefer explicit endpoint metadata, preserve ignore verdicts for duplicate IDs, and avoid guessed paths when kind boundaries are ambiguous.'}
lines=['# Five-PR fix follow-up','Snapshot: '+datetime.datetime.now(datetime.timezone.utc).isoformat(),'All changes were pushed to the existing PR branches. No PR was merged and no approval was submitted. The original workspace was left unchanged.','| PR / Trail | Head | Base | CI | Code review | Security monitor | Open findings |','|---|---|---|---|---|---|---:|']
for n in [97,111,128,174,190]:
 d=json.load(open(f'/tmp/entire-five/{n}-trail.json'));c=json.load(open(f'/tmp/entire-five/{n}-comments.json'));m=d['mergeability'];rs={r['runnerId']:r for r in d['runners']}
 states=[]
 for name in ['trail-review','trail-security']:
  r=rs[name];states.append(r.get('outcome') or r['state'])
 lines.append(f'| [#{n} / Trail {d["number"]}](https://entire.io/gh/entireio/entire-brain/trails/{d["number"]}) | {m["headSha"][:8]} | {d["base"]} | {m["checksStatus"]} | {states[0]} | {states[1]} | {len(c["comments"])} |')
 for kind in ['trail','comments','ci']:shutil.copy(f'/tmp/entire-five/{n}-{kind}.json',evidence/f'{n}-{kind}.json')
lines+=['','The Entire Gates check also requires an approval. Passing build/test CI is distinct from satisfying that approval gate. Security-monitor timeouts are missing review evidence, not successful security reviews.','', '## Changes and validation']
for n in notes:lines+=['',f'### PR #{n}',notes[n]]
lines+=['','Focused tests passed on the final code changes: document/index tests; all TestDistill tests; the complete factmerge package; six benchmark agent-state tests; and the semantic test selection, including snapshot filtering. CI status above comes from the current remote head.','', '## Review dispositions','Confirmed findings were fixed and resolved on their Trails with commit references and test results. Two findings were dismissed with evidence: the size/version-skew behavior already existed because the old writer was unbounded; the purported distill slice alias was confined to a privately loaded snapshot and had no escaping shared-state path.','', 'PR #128 targets the #127 branch. PR #174 targets the #88 feature branch; neither is a standalone merge to main.']
(out/'fix-followup.md').write_text('\n'.join(lines)+'\n')
print(out/'fix-followup.md')
PY
python3 /tmp/entire-five/report.py","max_output_tokens":300}));

