 open(f'/tmp/five-monitor-latest{n}.json','w').write(json.dumps(d))
 return {'pr':pr,'trail':n,'prState':state,'head':d.get('headSha'),'unresolved':d.get('unresolvedCount'),'runners':[{k:r.get(k) for k in ['runnerId','state','outcome','runId','startedAt']} for r in d.get('runners',[])],'gates':[{k:g.get(k) for k in ['gateKey','status','rationale']} for g in d.get('gates',[])],'monitors':[{k:m.get(k) for k in ['key','percentValue','state','evaluating','lastFailedAttempt']} for m in d.get('monitors',[])]}
with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
 for d in pool.map(read,pairs):print(json.dumps(d),flush=True)
PY","yield_time_ms":1000,"max_output_tokens":6000}));

