+package brainwire
+
+import (
+	"crypto/rand"
+	"encoding/json"
+	"strings"
+	"testing"
+)
+
+const foldTestArtifact = `{"manifest":{"repo_key":"honest","generated_at":"2026-01-02T03:04:05Z","brain_schema_version":"1.0"}}`
