// idempotent and the derived id must be a pure function of the normalized form.
func FuzzRecordIdentity(f *testing.F) {
	f.Add("Some Fact Text", "a.b.c,d.e.f")
	f.Add("  spaced   out  ", "A.B.C,,zzz")
	f.Add("  ", "x")
