package cli

import (
	"bytes"
	"context"
	"strings"
	"testing"
	"time"
)

// The transcript ingest path reads RAW AGENT OUTPUT: JSONL a third-party agent
// wrote, or a pretty-printed session document. It is the largest untrusted input
// the brain reads on every distill, and the existing FuzzParseDocumentConversation
// covers only the document parser in isolation. These harnesses drive the whole
// dispatcher (probe -> document-or-line decision -> scan) and the distill
// pre-processor, asserting the three properties an ingest path owes: never panic,
// never hang, never allocate without bound.
//
//	go test ./internal/cli -run xxx -fuzz FuzzName

// FuzzScanConversationTranscript drives the real entry point history and distill
// use, including the 4 KiB probe and the document/line fallback.
func FuzzScanConversationTranscript(f *testing.F) {
	f.Add([]byte(`{"role":"user","content":"hi"}` + "\n" + `{"role":"assistant","content":"yo"}` + "\n"))
	f.Add([]byte("{\n  \"messages\": [\n    {\"info\":{\"role\":\"user\"},\"parts\":[{\"type\":\"text\",\"text\":\"hi\"}]}\n  ]\n}"))
	f.Add([]byte("{\n  \"messages\": [\n"))
	f.Add([]byte("{" + strings.Repeat(" ", 5000) + "\n}"))
	f.Add([]byte("\x00\x01\x02"))
	f.Add([]byte(""))
	f.Add(append([]byte(`{"type":"user","message":{"content":"`), append(bytes.Repeat([]byte("x"), 2*1024*1024), []byte(`"}}`)...)...))

	f.Fuzz(func(t *testing.T, data []byte) {
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()
		if _, err := scanConversationTranscriptFileContext(ctx, bytes.NewReader(data), "fuzz.jsonl"); err == nil {
			// A successful scan must also survive being scanned again: the
			// source digest is a stability claim about the same bytes.
			if _, err := scanConversationTranscriptFileContext(ctx, bytes.NewReader(data), "fuzz.jsonl"); err != nil {
				t.Fatalf("re-scanning identical bytes failed the second time: %v", err)
			}
		}
	})
}

// FuzzScanLineConversationDigest asserts the line scanner's source digest is a
// pure function of the bytes consumed. The digest is what later proves an
// expansion re-parsed the same content, so an unstable digest silently
// invalidates every stored anchor.
func FuzzScanLineConversationDigest(f *testing.F) {
	f.Add([]byte(`{"role":"user","content":"a"}` + "\n" + `{"role":"assistant","content":"b"}`))
	f.Add([]byte("not json\n{\n"))
	f.Add([]byte("\n\n\n"))
	f.Fuzz(func(t *testing.T, data []byte) {
		first, err1 := scanLineConversation(bytes.NewReader(data))
		second, err2 := scanLineConversation(bytes.NewReader(data))
		if (err1 == nil) != (err2 == nil) {
			t.Fatalf("scanning identical bytes disagreed on error: %v vs %v", err1, err2)
		}
		if err1 != nil {
			return
		}
		if first.SourceDigest != second.SourceDigest {
			t.Fatalf("source digest is not a function of the bytes: %q vs %q", first.SourceDigest, second.SourceDigest)
		}
		if len(first.Exchanges) != len(second.Exchanges) {
			t.Fatalf("exchange count is not deterministic: %d vs %d", len(first.Exchanges), len(second.Exchanges))
		}
	})
}

// FuzzDistillDocumentConversation drives the distill pre-processor, whose
// contract is a strict line-for-line correspondence with the input document: a
// fact's provenance anchor points at a line number in the ORIGINAL transcript, so
// an off-by-one here mis-attributes evidence.
func FuzzDistillDocumentConversation(f *testing.F) {
	f.Add("{\n  \"messages\": [\n    {\"info\":{\"role\":\"user\"},\"parts\":[{\"type\":\"text\",\"text\":\"hi\"}]}\n  ]\n}")
	f.Add("{\n\"messages\":[]\n}")
	f.Add("{")
	f.Add("")
	f.Fuzz(func(t *testing.T, content string) {
		out, ok := distillDocumentConversation(content)
		if !ok {
			return
		}
		inLines := strings.Count(content, "\n") + 1
		outLines := strings.Count(out, "\n") + 1
		if inLines != outLines {
			t.Fatalf("line correspondence broken: input has %d lines, output %d", inLines, outLines)
		}
	})
}

// FuzzParseDocumentConversationLines pins the anchor invariant of the document
// parser: every reported message line must be a real 1-based line of the input,
// or a stored anchor points outside the file it cites.
func FuzzParseDocumentConversationLines(f *testing.F) {
	f.Add("{\n  \"messages\": [\n    {\"info\":{\"role\":\"user\"},\"parts\":[{\"type\":\"text\",\"text\":\"hi\"}]}\n  ]\n}")
	f.Add("{\n\"messages\":[{\"info\":{\"role\":\"assistant\"},\"parts\":[{\"type\":\"tool\"}]}]\n}")
	f.Add("{\n\"a\":1,\n\"messages\":[")
	f.Fuzz(func(t *testing.T, content string) {
		messages, ok := parseDocumentConversation(content)
		if !ok {
			return
		}
		maxLine := strings.Count(content, "\n") + 1
		for _, m := range messages {
			if m.Line < 1 || m.Line > maxLine {
				t.Fatalf("message anchored at line %d, outside the document's 1..%d", m.Line, maxLine)
			}
		}
	})
}
package gitmeta

import (
	"strings"
	"testing"

	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/storage/memory"
)

// These harnesses assert the robustness invariant every record-encoding surface
// owes once the git-meta store is shared (P1): arbitrary target values, keys and
// tree layouts must produce an ERROR, never a panic, and never a silently
// corrupting round trip. Run one with:
//
//	go test ./internal/factgitmeta/gitmeta -run xxx -fuzz FuzzName

// FuzzTreePath drives the whole path-encoding surface with an arbitrary target
// type, target value and key. Every entry point validates before encoding, so no
// input may panic: a value the encoder cannot express must come back as an error.
func FuzzTreePath(f *testing.F) {
	f.Add("commit", "abc123", "brain:facts")
	f.Add("branch", "main", "brain:entities")
	f.Add("project", "", "brain:entity:6162")
	f.Add("path", "a/b/c", "k")
	f.Add("change-id", "I1", "k")
	f.Add("commit", "a", "k") // one-char shard candidate
	f.Add("commit", "", "k")  // empty value
	f.Add("branch", "é", "k")
	f.Add("commit", "ab\x00cd", "k")

	f.Fuzz(func(t *testing.T, typ, value, key string) {
		tt, err := ParseTargetType(typ)
		if err != nil {
			return
		}
		target := Target{Type: tt, Value: value}
		for _, fn := range []func() (string, error){
			func() (string, error) { return TreePath(target, key) },
			func() (string, error) { return ListDirPath(target, key) },
			func() (string, error) { return SetDirPath(target, key) },
			func() (string, error) { return TombstonePath(target, key) },
			func() (string, error) { return ListEntryTombstonePath(target, key, "1-abcde") },
			func() (string, error) { return SetMemberTombstonePath(target, key, "member") },
		} {
			path, err := fn()
			if err != nil {
				continue
			}
			// An accepted path must be usable as a tree path: no empty
			// components, or BuildTree rejects what the encoder produced.
			for _, comp := range strings.Split(path, "/") {
				if comp == "" {
					t.Fatalf("encoded path %q has an empty component (type=%q value=%q key=%q)", path, typ, value, key)
				}
			}
		}
	})
}

// FuzzParseTarget asserts the wire parser never panics and that anything it
// accepts survives String() -> ParseTarget unchanged.
func FuzzParseTarget(f *testing.F) {
	f.Add("commit:abc123")
	f.Add("project")
	f.Add("branch:main")
	f.Add("path:a/b")
	f.Add("commit:")
	f.Add(":::")
	f.Fuzz(func(t *testing.T, s string) {
		target, err := ParseTarget(s)
		if err != nil {
			return
		}
		again, err := ParseTarget(target.String())
		if err != nil {
			t.Fatalf("re-parsing an accepted target failed: %v (target=%#v)", err, target)
		}
		if again != target {
			t.Fatalf("target round trip changed the value: %#v -> %#v", target, again)
		}
	})
}

// FuzzMaterializeRoundTrip is the security-relevant property for a SHARED
// git-meta ref: a tree another member wrote is untrusted input. Materializing it
// and re-serializing the result — exactly what MetaStore.Update does on every
// write — must never panic, whatever leaf paths the tree carries.
func FuzzMaterializeRoundTrip(f *testing.F) {
	f.Add("commit/ab/abc123/brain:facts/__value", "v")
	f.Add("project/brain:entity:6162/__list/1-abcde", "sha")
	f.Add("branch/aa/main/k/__set/deadbeef", "m")
	f.Add("commit/ab/abc123/__tombstones/k/__deleted", "")
	f.Add("path/a/b/__target__/k/__value", "v")
	f.Add("commit/ab/a/k/__value", "v") // one-char target value
	f.Add("commit/ab//k/__value", "v")  // empty target value

	f.Fuzz(func(t *testing.T, path, content string) {
		store := memory.NewStorage()
		root, err := BuildTree([]blobFile{{path: path, content: content}}, store)
		if err != nil {
			return // the encoder refused to build it; nothing to materialize
		}
		tree, err := object.GetTree(store, root)
		if err != nil {
			t.Fatalf("reading back a tree we just wrote: %v", err)
		}
		state, err := Materialize(tree)
		if err != nil {
			return // a malformed tree is an error by contract
		}
		// The write half of the same loop MetaStore.updateLocked runs.
		out := memory.NewStorage()
		if _, err := Serialize(state, out); err != nil {
			return // refusing to re-encode is fine; panicking is not
		}
	})
}

// FuzzApplyMutation drives the state machine the sync path runs between
// materialize and serialize.
func FuzzApplyMutation(f *testing.F) {
	f.Add("set", "commit", "abc123", "k", "v", int64(0))
	f.Add("list:push", "project", "", "brain:entity:61", "sha", int64(1))
	f.Add("set:add", "branch", "main", "k", "m", int64(2))
	f.Add("rm", "commit", "abc", "k", "", int64(3))

	f.Fuzz(func(t *testing.T, op, typ, value, key, val string, nowMS int64) {
		tt, err := ParseTargetType(typ)
		if err != nil {
			return
		}
		state := State{}.Apply(Mutation{
			Op:     MutationOp(op),
			Target: Target{Type: tt, Value: value},
			Key:    key,
			Value:  val,
			NowMS:  nowMS,
		})
		store := memory.NewStorage()
		_, _ = Serialize(state, store)
	})
}
package brainwire

// Canonical encoding for the brain wire artifact (milestone P1.M1.3).
//
// The default Go encoding/json round trip is byte-stable only within Go. It
// relies on four implementation details that no other language shares: HTML
// escaping, struct declaration order, `omitempty`, and RFC3339Nano time
// formatting. Anything that must be signed, content-hashed, or byte-compared
// ACROSS implementations goes through CanonicalMarshal / Canonicalize instead.
//
// The canonical form is a profile of RFC 8785 (JSON Canonicalization Scheme)
// restricted to this schema:
//
//  1. No HTML escaping. `<`, `>`, `&` and every other non-control code point is
//     emitted as raw UTF-8. (Affects repo_key, default_branch, branch, path,
//     media_type, provider.)
//  2. Object keys are sorted LEXICOGRAPHICALLY by UTF-16 code unit, never in Go
//     struct declaration order. So "brain_schema_version" precedes "repo_key"
//     even though the struct declares RepoKey first.
//  3. Optional fields are omitted when — and only when — they equal their
//     omitted default (see canonicalArtifact's field table, which mirrors the
//     `omitempty` tags in contract.go). An explicit `"size":0` or `"tree":""`
//     is NON-canonical input and is normalized to omission. A JSON null and an
//     empty array are both treated as absent. Required fields (no `omitempty`)
//     are ALWAYS emitted and are zero-filled when the input omits them.
//  4. Time: generated_at is converted to UTC and TRUNCATED to whole seconds,
//     then written with a literal "Z" suffix — never "+00:00", never a
//     fractional part. Sub-second input TRUNCATES (it does not error), so
//     "...T12:00:00Z" and "...T12:00:00.123456789Z" canonicalize identically.
//     Callers that need sub-second fidelity must not use this contract.
//  5. Numbers: decimal integers only, within ±2^53 (the range every IEEE-754
//     double-based parser represents exactly). No exponent, no fraction, no
//     leading zeros, no leading `+`, no `-0` (normalized to `0`). A fractional
//     or exponent literal, or a magnitude beyond 2^53, is rejected rather than
//     rounded.
//  6. Strings: valid UTF-8, minimally escaped. Only `"`, `\` and C0 controls
//     are escaped; C0 controls use the short forms \b \f \n \r \t where they
//     exist and lowercase \u00xx otherwise.
//
// No JSON tag in contract.go changes: the tags are the contract, and a tag
// change would be a major schema bump. This file only constrains how the
// existing tags are serialized.
//
// Unknown fields (those a newer additive minor introduced, per the
// tolerant-reader rule) are PRESERVED and canonically re-emitted. Their omitted
// defaults are unknowable to this reader, so their values pass through
// unchanged apart from key ordering, string escaping, and number syntax.

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf16"
	"unicode/utf8"
)

// CanonicalTimeLayout is the only timestamp form a canonical artifact may
// contain: RFC 3339, UTC, whole seconds, literal "Z".
const CanonicalTimeLayout = "2006-01-02T15:04:05Z"

// CanonicalMarshal encodes a BrainArtifact in the canonical form described at
// the top of this file. Two implementations that agree on the artifact's
// logical content MUST produce identical bytes, which makes the output safe to
// sign or content-hash across implementations.
func CanonicalMarshal(a BrainArtifact) ([]byte, error) {
	// Serialize with Go's encoder purely as a structural bridge (HTML escaping
	// off per rule 1), then run the same normalizer foreign bytes take. Having
	// exactly one normalization path is what guarantees
	// CanonicalMarshal(a) == Canonicalize(anyEncodingOf(a)).
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(a); err != nil {
		return nil, fmt.Errorf("brainwire: marshal artifact: %w", err)
	}
	return Canonicalize(buf.Bytes())
}

// Canonicalize normalizes arbitrary (including non-Go-produced) artifact bytes
// into the canonical form. It is idempotent:
// Canonicalize(Canonicalize(b)) == Canonicalize(b).
//
// It fails on input that cannot be expressed canonically without changing
// meaning: malformed JSON, a non-object artifact, a known field with the wrong
// JSON type, a non-integer number, or an unparseable generated_at.
func Canonicalize(raw []byte) ([]byte, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()

	// Token-level decode rather than json.Decoder.Decode: Go's decoder keeps
	// the LAST occurrence of a duplicated object member, so a signature checked
	// over re-canonicalized bytes would validate transported bytes whose
	// first-occurrence values a first-wins parser (common elsewhere) reads
	// instead — a cross-parser differential in the exact layer built to prevent
	// one. Canonical form therefore rejects duplicate members outright, as
	// RFC 8785 pipelines conventionally do.
	v, err := decodeCanonicalValue(dec, 0)
	if err != nil {
		return nil, fmt.Errorf("brainwire: decode artifact: %w", err)
	}
	if _, err := dec.Token(); !errors.Is(err, io.EOF) {
		return nil, errors.New("brainwire: trailing data after artifact")
	}

	obj, ok := v.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("brainwire: artifact must be a JSON object, got %s", jsonKindOf(v))
	}
	norm, err := normalizeObject(canonicalArtifact, obj)
	if err != nil {
		return nil, err
	}
	return encodeCanonical(norm)
}

// CanonicalUnmarshal canonicalizes raw and decodes it into out with the
// tolerant-reader rules (unknown fields ignored, see contract.go). The decoded
// artifact's GeneratedAt is already UTC-truncated, so CanonicalMarshal(*out)
// reproduces Canonicalize(raw) exactly — except when raw carried unknown
// fields, which the typed decode necessarily drops. Use Canonicalize, not this
// function, when the bytes must survive for a signature check.
func CanonicalUnmarshal(raw []byte, out *BrainArtifact) error {
	if out == nil {
		return errors.New("brainwire: CanonicalUnmarshal into nil artifact")
	}
	canon, err := Canonicalize(raw)
	if err != nil {
		return err
	}
	if err := json.Unmarshal(canon, out); err != nil {
		return fmt.Errorf("brainwire: decode canonical artifact: %w", err)
	}
	return nil
}

